/**
 * Text helpers that reproduce CPython `str` semantics that JavaScript does not
 * share out of the box.
 *
 * The two differences that matter here:
 *   - `len(str)` counts Unicode code points, while JS `String#length` counts
 *     UTF-16 code units (so "😀" is 1 in Python but 2 in JS).
 *   - `str.encode()` defaults to UTF-8 and yields a byte sequence.
 */

/** Number of Unicode code points, i.e. CPython's `len()` for `str`. */
export function codePointCount(text) {
  let count = 0;
  for (const _ of text) count += 1;
  return count;
}

/**
 * UTF-8 encode `text`, returning an array of byte values (0..255).
 * Equivalent to CPython's `str.encode()` with the default codec.
 */
export function encodeUtf8(text) {
  const out = [];
  for (const character of text) {
    const cp = character.codePointAt(0);
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return out;
}

/**
 * Characters CPython's `str.strip()` treats as whitespace. JS `\s` covers most
 * of them but omits the C1/legacy separators U+001C..U+001F and U+0085.
 */
const PY_WHITESPACE = /[\s]/u;

/** CPython `str.strip()` with no argument. */
export function pyStrip(text) {
  let start = 0;
  let end = text.length;
  while (start < end && PY_WHITESPACE.test(text[start])) start += 1;
  while (end > start && PY_WHITESPACE.test(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

