/**
 * CPython `int(str)` reimplemented on top of BigInt.
 *
 * BigInt rather than Number because Python integers are unbounded: the error
 * message for an out-of-range build echoes the value back verbatim, so
 * `int("1000000000000000000000000000000")` has to survive the round trip
 * without being rounded into scientific notation.
 */

import { pyStrip } from './text.mjs';

/** Raised for input `int()` refuses, mirroring Python's ValueError. */
export class PyValueError extends Error {}

/** Any Unicode decimal digit is accepted by `int()`, not just ASCII 0-9. */
const DECIMAL_DIGIT = /\p{Nd}/u;
const INT_LITERAL = /^[+-]?\p{Nd}(?:_?\p{Nd})*$/u;

/**
 * Decimal value of a Unicode digit. Digits are laid out in contiguous runs of
 * ten per script, so walking back to the run's zero yields the value.
 */
function digitValue(character) {
  const cp = character.codePointAt(0);
  for (let offset = 0; offset < 10; offset += 1) {
    const candidate = cp - offset;
    if (!DECIMAL_DIGIT.test(String.fromCodePoint(candidate))) break;
    if (offset === 9) return 9;
  }
  for (let offset = 0; offset < 10; offset += 1) {
    if (!DECIMAL_DIGIT.test(String.fromCodePoint(cp - offset - 1))) return offset;
  }
  return 0;
}

/**
 * Parse `text` the way CPython's `int()` does for base 10: surrounding
 * whitespace is ignored, an optional sign may lead, and single underscores are
 * permitted between digits. Throws {@link PyValueError} otherwise.
 */
export function pyInt(text) {
  const stripped = pyStrip(text);
  if (!INT_LITERAL.test(stripped)) {
    throw new PyValueError(`invalid literal for int() with base 10: '${text}'`);
  }

  let sign = '';
  let body = stripped;
  if (body[0] === '+' || body[0] === '-') {
    sign = body[0] === '-' ? '-' : '';
    body = body.slice(1);
  }

  let digits = '';
  for (const character of body) {
    if (character === '_') continue;
    digits += String(digitValue(character));
  }
  return BigInt(sign + digits);
}

