/**
 * A stand-in for CPython's immutable `bytes` object.
 *
 * Backed by a plain array of integers in 0..255 — that is all the fidelity this
 * port needs, and it keeps the type printable, comparable and sliceable without
 * any binary-view machinery.
 */

import { encodeUtf8 } from './text.mjs';

const BACKSLASH = 0x5c;
const TAB = 0x09;
const NEWLINE = 0x0a;
const CARRIAGE_RETURN = 0x0d;
const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;
const PRINTABLE_LOW = 0x20;
const PRINTABLE_HIGH = 0x7e;

export class PyBytes {
  /** @param {Iterable<number>} values byte values in 0..255 */
  constructor(values = []) {
    this.values = Array.from(values);
  }

  /** `str.encode()` — UTF-8 by default. */
  static fromString(text) {
    return new PyBytes(encodeUtf8(text));
  }

  /** CPython `len(bytes)`. */
  get length() {
    return this.values.length;
  }

  /**
   * CPython `repr(bytes)`, which is what `print()` shows for a bytes object.
   *
   * Quoting follows `bytes_repr` in CPython: a single quote is preferred, and
   * only a payload that contains `'` but no `"` switches to double quotes.
   * Inside the literal, the backslash, the active quote and the three named
   * escapes are backslashed; printable ASCII is passed through; everything else
   * becomes a lowercase two-digit `\xNN`.
   */
  repr() {
    const hasSingle = this.values.includes(SINGLE_QUOTE);
    const hasDouble = this.values.includes(DOUBLE_QUOTE);
    const quoteByte = hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
    const quote = String.fromCharCode(quoteByte);

    let body = '';
    for (const byte of this.values) {
      if (byte === BACKSLASH) body += '\\\\';
      else if (byte === quoteByte) body += '\\' + quote;
      else if (byte === TAB) body += '\\t';
      else if (byte === NEWLINE) body += '\\n';
      else if (byte === CARRIAGE_RETURN) body += '\\r';
      else if (byte >= PRINTABLE_LOW && byte <= PRINTABLE_HIGH) body += String.fromCharCode(byte);
      else body += '\\x' + byte.toString(16).padStart(2, '0');
    }
    return `b${quote}${body}${quote}`;
  }

  /** `print()` renders a bytes object through `repr()`. */
  toString() {
    return this.repr();
  }
}

