/**
 * The slice of CPython's `struct` module that `construct` leans on for its
 * fixed-width integer fields: packing an integer into little/big-endian bytes
 * with the module's exact range-check error text.
 */

/** Mirrors `struct.error`. */
export class StructError extends Error {
  constructor(message) {
    super(message);
    this.name = 'StructError';
  }
}

/**
 * Pack `value` (a BigInt) as an integer of `size` bytes.
 *
 * `code` is the single-character struct format letter ('B', 'h', ...) and is
 * only used to build the error message, which `struct` phrases in terms of the
 * letter and the inclusive bounds it implies.
 */
export function packInteger(value, { code, size, signed, little }) {
  const bits = BigInt(size * 8);
  const low = signed ? -(1n << (bits - 1n)) : 0n;
  const high = signed ? (1n << (bits - 1n)) - 1n : (1n << bits) - 1n;

  if (typeof value !== 'bigint') {
    throw new StructError('required argument is not an integer');
  }
  if (value < low || value > high) {
    throw new StructError(`'${code}' format requires ${low} <= number <= ${high}`);
  }

  const unsigned = value < 0n ? value + (1n << bits) : value;
  const bytes = [];
  for (let index = 0; index < size; index += 1) {
    bytes.push(Number((unsigned >> BigInt(index * 8)) & 0xffn));
  }
  if (!little) bytes.reverse();
  return bytes;
}

