/**
 * The `construct` exception hierarchy.
 *
 * Every ConstructError carries the parsing/building *path* and prefixes its
 * message with it, which is why the rendered exception spans two lines:
 *
 *     construct.core.FormatFieldError: Error in path (building)
 *     struct '<B' error during building, given value 256
 */

export class ConstructError extends Error {
  constructor(message = '', path = null) {
    super(path ? `Error in path ${path}\n${message}` : message);
    this.name = 'ConstructError';
    /** Dotted name used when the traceback prints the exception. */
    this.pythonName = 'construct.core.ConstructError';
    this.path = path;
  }
}

/** Raised when the underlying stream cannot supply/accept the exact bytes. */
export class StreamError extends ConstructError {
  constructor(message, path) {
    super(message, path);
