 * `construct.core` — the `Construct` base class and the two subconstructs this
 * program uses: `FormatField` (fixed-width numbers) and `Bytes` (raw payloads).
 */

import { PyBytes } from '../python/bytes.mjs';
import { packInteger, StructError } from '../python/struct.mjs';
import { FormatFieldError } from './errors.mjs';
import { ByteStream, streamWrite } from './stream.mjs';

/** The path construct reports while building at the top level. */
const BUILDING_PATH = '(building)';

/**
 * Base class for every construct.
 *
 * `build()` opens a stream, delegates to `_build()` and returns the accumulated
 * bytes — matching `Construct.build` / `Construct.build_stream`.
 */
export class Construct {
  build(obj, context = {}) {
    const stream = new ByteStream();
    return this.buildStream(obj, stream, context);
  }

  buildStream(obj, stream, context = {}) {
    this._build(obj, stream, context, BUILDING_PATH);
    return stream.getValue();
  }

  /* eslint-disable-next-line no-unused-vars */
  _build(obj, stream, context, path) {
    throw new Error('_build must be implemented by a subclass');
  }
}

/**
 * A fixed-size number backed by a `struct` format such as `'<B'`.
 *
 * When `struct` refuses the value, construct swallows the `struct.error` and
 * re-raises it as a FormatFieldError naming the format string and the offending
 * value.
 */
export class FormatField extends Construct {
  constructor({ endianity, code, size, signed }) {
    super();
    this.fmtstr = `${endianity}${code}`;
    this.length = size;
    this.spec = { code, size, signed, little: endianity === '<' };
  }

  _build(obj, stream, context, path) {
    let data;
    try {
      data = packInteger(obj, this.spec);
    } catch (error) {
      if (error instanceof StructError) {
        throw new FormatFieldError(
          `struct '${this.fmtstr}' error during building, given value ${obj}`,
          path,
        );
      }
      throw error;
    }
    stream.write(data);
  }
}

/**
 * `Bytes(length)` — a raw byte field of an exact size.
 *
 * Building requires a bytes object whose length matches; anything else trips the
 * length check inside `stream_write`.
 */
export class BytesField extends Construct {
  constructor(length) {
    super();
    this.length = length;
  }

  _build(obj, stream, context, path) {
    const data = obj instanceof PyBytes ? obj.values : Array.from(obj);
    streamWrite(stream, data, this.length, path);
    return obj;
  }
}

/** Factory mirroring the callable `construct.Bytes`. */
export function Bytes(length) {
  return new BytesField(length);
}

