/**
 * argparse's control-flow exceptions.
 *
 * argparse never returns an error to its caller: it either raises ArgumentError
 * (which the parser catches and turns into a `parser.error()` message) or exits
 * the process. SystemExit models the latter so the entry point stays in charge
 * of the actual exit.
 */

/** A per-argument failure, e.g. a `type=` callable rejecting its input. */
export class ArgumentError extends Error {
  constructor(argument, message) {
    super(`argument ${argument}: ${message}`);
    this.name = 'ArgumentError';
    this.argument = argument;
  }
}

/** Mirrors `SystemExit`: unwound by the entry point, which sets the exit code. */
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

