/**
 * Renders the `usage:` line and the `--help` body exactly as argparse's
 * HelpFormatter does for a parser made up of optional arguments.
 */

const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** `-h, --help` / `--a A` — how an action is spelled in the options list. */
function formatInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
}

/** `[-h]` / `--a A` — how an action is spelled inside the usage line. */
function formatUsagePart(action) {
  const option = action.optionStrings[0];
  const body = action.nargs === 0 ? option : `${option} ${action.metavar}`;
  return action.required ? body : `[${body}]`;
}

export function formatUsage(prog, actions) {
  const parts = actions.map(formatUsagePart).join(' ');
  return `usage: ${prog}${parts ? ` ${parts}` : ''}\n`;
}

export function formatHelp(prog, actions) {
  let out = formatUsage(prog, actions);

  const invocations = actions.map(formatInvocation);
  // argparse aligns help text two columns past the widest indented invocation,
  // capped at max_help_position.
  const widest = Math.max(0, ...invocations.map((text) => text.length + INDENT));
  const helpPosition = Math.min(widest + 2, MAX_HELP_POSITION);

  out += '\noptions:\n';
  for (const [index, action] of actions.entries()) {
    const invocation = invocations[index];
    if (!action.help) {
      out += `${' '.repeat(INDENT)}${invocation}\n`;
      continue;
    }
    const head = `${' '.repeat(INDENT)}${invocation}`;
    if (head.length <= helpPosition - 2) {
      out += `${head}${' '.repeat(helpPosition - head.length)}${action.help}\n`;
    } else {
      out += `${head}\n${' '.repeat(helpPosition)}${action.help}\n`;
    }
  }
  return out;
}

