/**
 * A focused reimplementation of `argparse.ArgumentParser` covering the optional
 * arguments this program declares: `type=`, `required=`, the auto-added
 * `-h/--help`, `--opt=value` and `--opt value` forms, prefix abbreviation, and
 * argparse's exact error text and exit codes.
 */

import { ArgumentError, SystemExit } from './errors.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';

/** `^-\d+$|^-\d*\.\d+$` — argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class Action {
  constructor({ optionStrings, dest, metavar, type, required, nargs, help, isHelp }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.metavar = metavar;
    this.type = type;
    this.required = required;
    this.nargs = nargs;
    this.help = help;
    this.isHelp = Boolean(isHelp);
  }
}

export class ArgumentParser {
  /**
   * @param {object} [options]
   * @param {string} [options.prog] program name in usage/error text; defaults to
   *   `basename(sys.argv[0])`, i.e. the script's own file name.
   * @param {(text: string) => void} [options.stdout]
   * @param {(text: string) => void} [options.stderr]
   */
  constructor({ prog, stdout, stderr } = {}) {
    this.prog = prog ?? defaultProg();
    this.writeOut = stdout ?? ((text) => process.stdout.write(text));
    this.writeErr = stderr ?? ((text) => process.stderr.write(text));
    this.actions = [];
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      nargs: 0,
      help: 'show this help message and exit',
      isHelp: true,
    });
  }

  addArgument(names, { type = null, required = false, nargs = 1, help = null, metavar, isHelp } = {}) {
    const optionStrings = Array.isArray(names) ? names : [names];
    const longest = optionStrings.find((name) => name.startsWith('--')) ?? optionStrings[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');

    const action = new Action({
      optionStrings,
      dest,
      metavar: metavar ?? dest.toUpperCase(),
      type,
      required,
      nargs,
      help,
      isHelp,
    });
    this.actions.push(action);
    for (const option of optionStrings) this.optionStringActions.set(option, action);
    return action;
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  printHelp() {
    this.writeOut(this.formatHelp());
  }

  /** `parser.error()`: usage + message on stderr, then exit status 2. */
  error(message) {
    this.writeErr(this.formatUsage());
    this.writeErr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = null;
    }

    const extras = [];
    const seen = new Set();
    let index = 0;

    while (index < argv.length) {
      const token = argv[index];

      // A bare `--` ends option parsing; argparse leaves it and everything
      // after it to the positional pass, where an all-optional parser has no
      // home for any of it.
      if (token === '--') {
        extras.push(...argv.slice(index));
        break;
      }

      const parsed = this.parseOptional(token);
      if (parsed === null) {
        extras.push(token);
        index += 1;
        continue;
      }

      const { optionString, explicitValue } = parsed;
      const action = this.optionStringActions.get(optionString);
      if (action === undefined) {
        extras.push(token);
        index += 1;
        continue;
      }

      index += 1;
      if (action.nargs === 0) {
        if (explicitValue !== null) {
          this.handleArgumentError(
            new ArgumentError(optionString, `ignored explicit argument '${explicitValue}'`),
          );
        }
        if (action.isHelp) {
          this.printHelp();
          throw new SystemExit(0);
        }
        seen.add(action);
        continue;
      }

      let raw = explicitValue;
      if (raw === null) {
        if (index >= argv.length || this.parseOptional(argv[index]) !== null) {
          this.handleArgumentError(new ArgumentError(optionString, 'expected one argument'));
        }
        raw = argv[index];
        index += 1;
      }

      namespace[action.dest] = this.convert(action, optionString, raw);
      seen.add(action);
    }

    const missing = this.actions.filter((action) => action.required && !seen.has(action));
    if (missing.length > 0) {
      const names = missing.map((action) => action.optionStrings[0]).join(', ');
      this.error(`the following arguments are required: ${names}`);
    }

    return [namespace, extras];
  }

  /**
   * `_parse_optional`: decide whether `token` is an option, and if so which one
   * plus any `=`-attached value. Returns null when the token is a plain value.
   */
  parseOptional(token) {
    if (token.length === 0) return null;
    if (token[0] !== '-') return null;
    if (this.optionStringActions.has(token)) return { optionString: token, explicitValue: null };
    if (token.length === 1) return null;

    const equals = token.indexOf('=');
    if (equals !== -1) {
      const head = token.slice(0, equals);
      if (this.optionStringActions.has(head)) {
        return { optionString: head, explicitValue: token.slice(equals + 1) };
      }
    }

    const matches = this.getOptionTuples(token);
    if (matches.length > 1) {
      const options = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];

    // Looks like a negative number and no option does: it is a value.
    if (NEGATIVE_NUMBER.test(token) && !this.hasNegativeNumberOptions()) return null;
    // Contains a space: argparse treats it as a value, not an option.
    if (token.includes(' ')) return null;

    return { optionString: token, explicitValue: null };
  }

  /** `_get_option_tuples`: long-option prefix abbreviation. */
  getOptionTuples(token) {
    if (!token.startsWith('--')) return [];
    const equals = token.indexOf('=');
    const prefix = equals === -1 ? token : token.slice(0, equals);
    const explicitValue = equals === -1 ? null : token.slice(equals + 1);

    const matches = [];
    for (const optionString of this.optionStringActions.keys()) {
      if (optionString.startsWith('--') && optionString.startsWith(prefix)) {
        matches.push({ optionString, explicitValue });
      }
    }
    return matches;
  }

  hasNegativeNumberOptions() {
    for (const optionString of this.optionStringActions.keys()) {
      if (NEGATIVE_NUMBER.test(optionString)) return true;
    }
    return false;
  }

  convert(action, optionString, raw) {
    if (action.type === null) return raw;
    try {
      return action.type(raw);
    } catch {
      const typeName = action.type.typeName ?? action.type.name ?? 'value';
      this.handleArgumentError(
        new ArgumentError(optionString, `invalid ${typeName} value: '${raw}'`),
      );
      return null;
    }
  }

  handleArgumentError(error) {
    this.error(error.message);
  }
}

function defaultProg() {
  const scriptPath = process.argv[1] ?? '';
  const separator = scriptPath.lastIndexOf('/');
  return separator === -1 ? scriptPath : scriptPath.slice(separator + 1);
}

