/**
 * Reproduces what the frozen reference program prints to stderr when a
 * `construct` build fails: the chained CPython traceback followed by
 * PyInstaller's bootloader complaint, then exit status 1.
 *
 * Two details of the reference behaviour are worth calling out:
 *
 *   - The interpreter frames below are fixtures — the reference binary's own
 *     `construct/core.py` line numbers — because a JS port has no Python stack
 *     to introspect.
 *   - Traceback frames only show a source line when `linecache` can actually
 *     open the recorded file name. The frozen binary records the *relative*
 *     path "test8.py", so the source lines and carets appear only when the
 *     process is run from a directory that happens to contain a test8.py, and
 *     vanish otherwise. This module reproduces that, quirk and all.
 */

import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

const SCRIPT = 'test8.py';
const CORE = 'construct/core.py';
const ENTRY_LINE = 21;
const BODY_INDENT = ' '.repeat(4);

/** Frames between the failing statement and the raise, per exception type. */
const CONSTRUCT_FRAMES = {
  FormatFieldError: [
    [CORE, 452, 'build'],
    [CORE, 464, 'build_stream'],
    [CORE, 1167, '_build'],
  ],
  StreamError: [
    [CORE, 452, 'build'],
    [CORE, 464, 'build_stream'],
    [CORE, 970, '_build'],
    [CORE, 195, 'stream_write'],
  ],
};

/** Frames of the chained exception, when the failure wraps another one. */
const CONTEXT_FRAMES = {
  FormatFieldError: [[CORE, 1165, '_build']],
};

const frame = (file, line, name) => `  File "${file}", line ${line}, in ${name}\n`;

/**
 * `linecache.getline()`: read line `line` of `file`, resolved against the
 * current working directory. Returns null when the file is not there, which is
 * the signal to omit the source line from the frame.
 */
function getLine(file, line) {
  try {
    const text = readFileSync(resolve(process.cwd(), file), 'utf8');
    return text.split('\n')[line - 1]?.trim() || null;
  } catch {
    return null;
  }
}

/**
 * Render one `File "..."` frame plus, when the source is available, the stripped
 * source line and the `^^^^` run underlining the sub-expression that raised.
 *
 * Caret columns come from the code object, not the file, so they are supplied
 * by the caller. CPython omits the carets entirely when the anchor spans the
 * whole line.
 */
function frameWithSource(file, line, name, expression = null) {
  let out = frame(file, line, name);
  const source = getLine(file, line);
  if (source === null) return out;

  out += `${BODY_INDENT}${source}\n`;
  if (expression !== null) {
    const column = source.indexOf(expression);
    if (column !== -1) {
      out += `${' '.repeat(BODY_INDENT.length + column)}${'^'.repeat(expression.length)}\n`;
    }
  }
  return out;
}

/**
 * @param {Error} error the ConstructError that escaped `main()`
 * @param {{line: number, expression: string}} site the source line in `main()`
 *   that raised, and the sub-expression the carets point at.
 */
export function formatTraceback(error, site) {
  let out = '';

  const contextFrames = CONTEXT_FRAMES[error.name];
  if (error.contextError && contextFrames) {
    out += 'Traceback (most recent call last):\n';
    for (const [file, line, name] of contextFrames) out += frame(file, line, name);
    out += `${error.contextError.pythonName}: ${error.contextError.message}\n`;
    out += '\nDuring handling of the above exception, another exception occurred:\n\n';
  }

  out += 'Traceback (most recent call last):\n';
  out += frameWithSource(SCRIPT, ENTRY_LINE, '<module>');
  out += frameWithSource(SCRIPT, site.line, 'main', site.expression);
  for (const [file, line, name] of CONSTRUCT_FRAMES[error.name] ?? []) {
    out += frame(file, line, name);
  }
  out += `${error.pythonName}: ${error.message}\n`;
  return out;
}

/** Print the traceback plus the bootloader line, exactly as the binary does. */
export function printTraceback(error, site, write = (text) => process.stderr.write(text)) {
  write(formatTraceback(error, site));
  write(`[PYI-${process.pid}:ERROR] Failed to execute script 'test8' due to unhandled exception!\n`);
}

