#!/usr/bin/env node
/**
 * Node.js port of dataset/construct/test8.py.
 *
 * Reads three options, builds a one-byte unsigned integer for each of `--a` and
 * `--b` and a raw byte field for `--c`, then prints the three bytes objects.
 */

import { SystemExit } from './lib/argparse/errors.mjs';
import { ArgumentParser } from './lib/argparse/parser.mjs';
import { intType, strType } from './lib/argparse/types.mjs';
import { ConstructError } from './lib/construct/errors.mjs';
import construct from './lib/construct/index.mjs';
import { PyBytes } from './lib/python/bytes.mjs';
import { codePointCount } from './lib/python/text.mjs';
import { printTraceback } from './lib/runtime/traceback.mjs';

/**
 * The reference build is frozen as `test8_executable`, and argparse derives its
 * usage/error prefix from `basename(sys.argv[0])`. Pin it so this port's
 * diagnostics match the reference byte for byte instead of saying `test8.mjs`.
 */
const PROG = 'test8_executable';

/**
 * Source locations of the three build calls in test8.py. A failed build prints
 * a traceback quoting the offending line, so the port has to carry the same
 * text and line numbers.
 */
const SITES = {
  format1: {
    line: 12,
    statement: 'format1 = construct.Int8ul.build(args.a)  # 构建第一个整数',
    expression: 'construct.Int8ul.build(args.a)',
  },
  format2: {
    line: 13,
    statement: 'format2 = construct.Int8ul.build(args.b)  # 构建第二个整数',
    expression: 'construct.Int8ul.build(args.b)',
  },
  format3: {
