      'format3 = construct.Bytes(length).build(args.c.encode())  # 构建字节串',
    expression: 'construct.Bytes(length).build(args.c.encode())',
  },
};

/** Run `build`, tagging any ConstructError with the source line that raised. */
function at(site, build) {
  try {
    return build();
  } catch (error) {
    if (error instanceof ConstructError) error.site = site;
