import { execFileSync } from 'node:child_process';

const strings = [
  'binary', 'end', 'packet', 'abcdef', '', 'a b', 'x\ty', 'q\\r', "z'q", 'd"e',
  "mix'\"both", '\x01\x02\x7f', 'hello world', '-5', '--x', 'a\nb', '  pad  ',
  '中文', '\u{1F600}', 'héllo', '=eq', 'tab\tend',
];

const run = (cmd, pre, args) => {
  try {
    const out = execFileSync(cmd, [...pre, ...args], { encoding: 'latin1', stdio: ['ignore', 'pipe', 'pipe'] });
    return { out, code: 0 };
  } catch (e) {
    return { out: String(e.stdout ?? ''), code: e.status };
  }
};

let fails = 0;
let total = 0;
for (let i = 0; i < 400; i += 1) {
  const a = Math.floor(Math.random() * 300) - 20;
  const b = Math.floor(Math.random() * 300) - 20;
  const c = strings[Math.floor(Math.random() * strings.length)];
  const args = ['--a', String(a), '--b', String(b), '--c', c];

  const py = run('/workspace/dataset/test8_executable', [], args);
  const js = run('node', ['/output/test8.mjs'], args);
  total += 1;
  if (py.out !== js.out || py.code !== js.code) {
    fails += 1;
    console.log('MISMATCH', JSON.stringify(args));
    console.log('  py', JSON.stringify(py));
    console.log('  js', JSON.stringify(js));
  }
}
console.log(`fuzz: ${total} cases, ${fails} stdout/exit-code mismatches`);

